import os, json

# Load all grids including test input
def load_grids():
    d = os.path.normpath(os.environ.get('RLM_SESSION_DIR', ''))
    if not d:
        return {}
    path = os.path.join(d, '../../sessions/', os.path.basename(d) + '.jsonl')
    G = {}
    try:
        with open(path) as f:
            txt = f.read()
    except Exception as e:
        print(f"Error loading: {e}")
        return {}

    # Parse using regex
    for m in __import__('re').finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', txt):
        k, h, w = m[1], int(m[2]), int(m[3])
        end = m.end()
        rows_txt = txt[end:end+h].strip().split('\n')[:h]
        valid = all(len(r) == w and all(x.isdigit() for x in r) for r in rows_txt)
        if valid:
            G[k] = [[int(x) for x in r] for r in rows_txt]
    return G

G = load_grids()
print("Available:", sorted(G.keys()))

for k, g in G.items():
