def transform(input_grid):
    N = len(input_grid)
    M = len(input_grid[0])
    output = [[0]* (2*M) for _ in range(2*N)]

    # TL
    for r in range(N):
        for c in range(M):
            output[r][c] = input_grid[r][c]

    # TR
    for r in range(N):
        for c in range(M):
            output[r][c+M] = input_grid[N-1-c][r]

    # BL
    for r in range(N):
        for c in range(M):
            output[r+N][c] = input_grid[c][N-1-r]

    # BR
    for r in range(N):
        for c in range(M):
            output[r+N][c+M] = input_grid[N-1-r][M-1-c]

    return output

result = transform(test_input)
print("Result grid:")
for row in result:
    print(' '.join(str(x) for x in row))

import json
print("\nJSON:", json.dumps(result))
